package platform

import (
	"bufio"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var hexColor = regexp.MustCompile(`^#[0-9a-fA-F]{6}$`)

// LoadOmarchyPalette reads the active theme generated by Omarchy at startup.
func LoadOmarchyPalette() (ThemePalette, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return ThemePalette{}, err
	}
	path := filepath.Join(home, ".local", "state", "omarchy", "current", "theme", "colors.toml")
	file, err := os.Open(path)
	if err != nil {
		return ThemePalette{}, err
	}
	defer file.Close()
	values := make(map[string]string)
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 1024), 1<<20)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 {
			continue
		}
		key, value := strings.TrimSpace(parts[0]), strings.Trim(strings.TrimSpace(parts[1]), `"'`)
		if key == "mode" || hexColor.MatchString(value) {
			values[key] = value
		}
	}
	if err := scanner.Err(); err != nil {
		return ThemePalette{}, err
	}
	p := ThemePalette{Mode: values["mode"], Background: values["background"], Foreground: values["foreground"], LightForeground: values["light_foreground"], DarkForeground: values["dark_foreground"], Accent: values["accent"], Muted: values["muted"], Selection: values["selection"], Red: values["red"], LighterBackground: values["lighter_background"]}
	if p.Background == "" || p.Foreground == "" {
		return ThemePalette{}, os.ErrInvalid
	}
	return p, nil
}
